// Original FM24 save snapshot, 3 July 2023. Unsupported club links are omitted.
(() => {
  const cache = new Map();
  const positions = codes => {
    const result = [];
    if (codes.includes('GK')) result.push('GK');
    if (codes.includes('SW')) result.push('SW');
    for (const [prefix, label] of [['D','D'],['WB','WB'],['M','M'],['AM','AM']]) {
      const sides = ['R','L','C'].filter(side => codes.includes(prefix+side));
      if (sides.length) result.push(`${label} (${sides.join('')})`);
    }
    if (codes.includes('DM')) result.push('DM');
    if (codes.includes('ST')) result.push('ST (C)');
    return result.join(', ');
  };
  globalThis.fmStartingClubSquad = club => {
    const data = globalThis.FM24_STARTING_SQUADS;
    if (!data || data.loaded.size !== data.parts || !club) return null;
    const fmId = String(club.fmId || ({sunderland:'722',ipswich:'667',leicester:'673'})[club.id] || '');
    const record = data.clubs[fmId];
    if (!record || !record.players.length) return null;
    const stats = data.leagues[record.leagueId];
    if (!stats || record.leagueId !== String(club.leagueId || record.leagueId)) return null;
    const key = fmId + ':' + club.league;
    if (cache.has(key)) return cache.get(key);
    const players = record.players.map(([uid,name,age,codes,values,rating]) => {
      const text = positions(codes);
      const group = codes.includes('GK') ? 'goalkeepers'
        : codes.some(code => ['DL','DC','DR','SW','WBL','WBR'].includes(code)) ? 'defenders'
        : codes.some(code => ['AML','AMC','AMR','ST'].includes(code)) ? 'forwards' : 'midfielders';
      return {uid,name,age,positions:text,group,rating,ratingRange:null,
        attributes:Object.fromEntries(data.attributes.map((label,index) => {
          const value = values.charCodeAt(index)-64;
          return [label,{low:value,high:value}];
        }))};
    });
    const snapshot = {players,kind:'starting-database',gameDate:data.gameDate,
      leagueName:club.league,sampleSize:stats.sampleSize,clubCount:stats.clubCount};
    cache.set(key,snapshot);
    return snapshot;
  };
})();

